      "derivations": [
        {
          "id": "step-1-1",
          "claim": "The circle action $t\\cdot(z,w)=(e^{4\\pi i t}z,e^{2\\pi i t}w)$ on $S^1\\times D^2$ has generic orbit slope $2\\lambda_V+\\mu_V$. The given pattern is one such orbit. The core $S^1\\times\\{0\\}$ has stabilizer of order $2$, while generic points have trivial stabilizer. Removing a tube about the regular orbit $P_{2,1}$ therefore gives a Seifert fibration of $X_{P_{2,1}}$ over an annulus with one exceptional point of multiplicity $2$. On the outer torus its regular-fiber slope is $2\\lambda_V+\\mu_V$.",
          "step": "1.1",
          "inputs": [
