          ]
        },
        {
          "id": "step-2-2",
          "claim": "By [F7], the companion torus $T_c$ is essential. Hence the whole exterior $M=E_{P_{2,1}(K)}$ is not atoroidal. Both pieces cut along $T_c$ are Seifert-fibered by steps 1.1 and 1.3.",
          "step": "2.2",
          "inputs": [
            "F1",
            "F2",
