          ]
        },
        {
          "fact": "F3",
          "source": "lem-kh-to-instanton-resolution-spectral-sequence",
          "source_section": "Statement",
          "quote": "Assume full AC. Let $D$ be a finite based diagram of a smooth knot $K\\subset S^3$ with ordered crossings $c_1<\\cdots<c_n$. The singular instanton resolution complex admits a finite filtration whose first page, with its first differential, is isomorphic to the reduced Khovanov cube of the reflected based diagram $\\overline D$. Its spectral sequence converges to $I^\\natural(K;\\mathbb Z)$. The cube sign at the edge changing $c_j$ is $(-1)^{\\sum_{i<j}v_i}$, and the edge operation is multiplication for a merge or comultiplication for a split. Thus its $E_2$ page is the reduced integral Khovanov cohomology of $\\overline D$. The claim includes coherent instanton orientations and the unlink group and saddle-map identifications; it asserts no diagram-invariance of intermediate pages.",
          "uses": [
            "1.1"
          ]
        }
