          ]
        },
        {
          "fact": "F5",
          "source": "lem-maximal-abelian-cover-cellular-chain-model",
          "source_section": "Statement",
          "quote": "Assume the Axiom of Choice. Let $L$ be a nonempty oriented smooth $r$-component link with $r\\ge1$, compact exterior $E_L$, and maximal abelian cover $E_L^{\\mathrm{ab}}\\to E_L$ with deck group $H\\cong\\mathbb Z^r$ and group ring $\\Lambda_r=\\mathbb Z[H]$. For any finite CW structure on $E_L$, the inverse-image cells and one chosen lift of each open cell form a finite-rank free $\\Lambda_r$ cellular chain complex. Its first homology is the absolute multivariable Alexander module $A_L=H_1(X_L^{\\mathrm{ab}};\\mathbb Z)$, with the deck action specified by the positive meridians.",
          "uses": [
