          ]
        },
        {
          "fact": "F3",
          "source": "lem-root-handlebody-pairing-nondegeneracy-and-gluing",
          "source_section": "Statement",
          "quote": "For the fixed root parameter, the normalized double-handlebody pairing on the admissible spine states of a marked handlebody is nondegenerate after quotienting by its radical. The inverse pairing defines the sewing map for gluing along a closed marked surface, and these maps satisfy the stated weighted Lagrangian anomaly correction.",
          "uses": [
