          ]
        },
        {
          "fact": "F8",
          "source": "thm-collar-neighborhood-theorem",
          "source_section": "Statement",
          "quote": "Assume $\\mathrm{AC}_\\omega$. Every smooth manifold with boundary has a smooth collar.",
          "uses": [
