      "derivations": [
        {
          "id": "step-1-1",
          "claim": "Parametrize the circle by a smooth regular embedding $\\gamma:S^1\\to\\mathbb R^2$, and let $n$ be its smooth unit normal obtained by rotating and normalizing its tangent. The map $T(s,r)=\\gamma(s)+rn(s)$ has invertible derivative at $r=0$. By [F1] and compactness it is a local diffeomorphism on a common strip $|r|<a$. It is injective after shrinking $a$: otherwise collisions for widths tending to zero would have a subsequence of their circle parameters converging; equality of the limiting images and injectivity of $\\gamma$ give the same limiting parameter, contrary to a local inverse there. Thus $T$ is a smooth two-sided annular coordinate.",
          "step": "1.1",
          "inputs": [
            "F1",
